#pragma once
// CSCI 41 -- Lab 06: Abstract Data Types
//
// IntSet: a set of distinct ints.
//
// PROVIDED. Do not edit this file. Implement everything in src/int_set.cpp.
//
// ---------------------------------------------------------------------
// THE ADT
//
// A set holds each value at most once, and does not promise any order.
// That is the whole abstraction. Nothing below should make you think about
// arrays -- except one function, and that one is discussed at the bottom.
//
// REPRESENTATION RULE FOR THIS LAB
//
// Store the values in a dynamic array that you allocate with new[] and free
// with delete[]. When it is full, allocate a bigger one and copy across.
// You may not use std::vector, std::set, or any other container here. The
// point of the lab is to own the memory yourself.
// ---------------------------------------------------------------------

class IntSet {
public:
    // Makes an empty set with a small starting capacity.
    IntSet();

    // Makes an empty set with room for initialCapacity values before it has
    // to grow.
    // PRECONDITION: initialCapacity > 0.
    explicit IntSet(int initialCapacity);

    // ---- the Rule of Three ------------------------------------------
    // This class owns memory, so the compiler's versions of these are
    // wrong: they would copy the POINTER and leave two objects believing
    // they own the same array.
    //
    // Each of these must give the new object its own array.
    IntSet(const IntSet& other);
    IntSet& operator=(const IntSet& other);
    ~IntSet();

    // ---- the set operations -----------------------------------------

    // Adds value if it is not already present.
    // Returns true if it was added, false if it was already there.
    bool insert(int value);

    // Removes value if present.
    // Returns true if it was removed, false if it was not there.
    bool remove(int value);

    // True if value is in the set.
    bool contains(int value) const;

    // How many values the set holds.
    int size() const;

    // True when size() == 0.
    bool isEmpty() const;

    // Removes everything. The set is reusable afterwards.
    void clear();

    // ---- a deliberate leak in the abstraction ------------------------
    //
    // How many values the set can hold before it next has to grow.
    //
    // This is NOT part of the idea of a set. A set built a different way
    // might have no meaningful capacity at all. It is here only so the
    // tests can check that growing works, and so that you can see it.
    //
    // Letting an implementation detail show through the interface like this
    // is a real decision with a real cost, and the handout asks you about
    // it. It is not an accident, and it is not good practice in general.
    int capacity() const;

private:
    int* data_;      // the array you allocate
    int  size_;      // how many of its slots are in use
    int  capacity_;  // how many slots it has

    // Returns the index of value in data_[0..size_-1], or -1 if absent.
    int indexOf(int value) const;

    // If data_ is full, replace it with a bigger array holding the same
    // values. Doubling the capacity is the expected strategy; the handout
    // explains why.
    void growIfNeeded();
};
